mapper.select:
SELECT un.id AS id, un.type AS type, un.title AS title, un.body AS body, un.target_url AS targetUrl, CASE WHEN un.is_read = 1 THEN TRUE ELSE FALSE END AS `read`, un.read_at AS readAt, un.created_at AS createdAt FROM user_notifications un WHERE un.user_id = #{userId} AND un.deleted = 0
AND un.is_read = 0
ORDER BY un.created_at DESC, un.id DESC LIMIT #{limit} OFFSET #{offset}
